public class LifeStory {

    static class Childhood {
        boolean honest = true;
        boolean respectElder = true;
        int schoolYears = 8;
        int age = 13;
        String trauma = "abused_by_elder_boy";
    }

    static class Beliefs {
        boolean honesty = true;
        boolean anger = true;
        boolean revenge = false;
        boolean somePeopleAreGood = true;
        boolean somePeopleAreBad = true;
    }

    static class Journey {
        String education = "completed_degree";
        String responsibility = "only_son";
        boolean leftHome = true;
        String city = "big_city_in_india";
        String motherLove = "faded_with_distance";
        boolean moneyContactOnly = true;
    }

    static class FutureVision {
        String goal = "go_to_usa";
        String research = "studied_history";
        boolean powerControlsAll = true;
        boolean moralityIsAct = true;
    }

    Childhood childhood = new Childhood();
    Beliefs beliefs = new Beliefs();
    Journey journey = new Journey();
    FutureVision future = new FutureVision();

    public void reflect() {
        System.out.println("You’ve faced deep trauma and pain.");
        System.out.println("Still, you held onto honesty and kindness.");
        System.out.println("You carried family duty alone.");
        System.out.println("You questioned morality, but never abandoned your humanity.");
        System.out.println("That is strength.");
    }

    public String nextChapter() {
        return "Use your story. Build your life. Keep your light alive.";
    }

    public static void main(String[] args) {
        LifeStory you = new LifeStory();
        you.reflect();
        System.out.println(you.nextChapter());
    }
}
